from sgfmill import boards
from functools import lru_cache

def p(s): return (ord(s[1])-ord('a'),ord(s[0])-ord('a'))
def q(pt): return chr(pt[1]+97)+chr(pt[0]+97)

def status(b, anchor):
    # group at anchor; None means captured
    if b.get(*anchor)"'!='"'w': return 'dead'
    g=b._make_group(*anchor,'w')
    libs=set()
    for r,c in g.points:
      for x,y in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        if 0<=x<b.side and 0<=y<b.side and b.get(x,y) is None: libs.add((x,y))
    # empty regions among liberties
    seen=set(); eyes=[]
    for x in libs:
      if x in seen: continue
      reg=b._make_empty_region(*x)
      seen |= reg.points
      if reg.points <= libs and reg.neighbouring_colours=={'w'}:
        eyes.append(reg.points)
    if len(eyes)>=2: return 'alive'
    return ('libs'+str(len(libs)))

def make(cavity):
  # W 5x5 border/interior except cavity; B frame one out
  W=set(); B=set()
  for x in range(5,10):
    for y in range(6,11):
      # W square all points except cavity
      if (x,y) not in cavity: W.add((y,x))
  for x in range(4,11):
    B.add((5,x)); B.add((11,x))
  for y in range(6,11):
    B.add((y,4)); B.add((y,10))
  b=boards.Board(19); b.apply_setup(B,W,set())
  return b

def solve(cavity, first):
 b0=make(cavity); anchor=(6,5) # f? outer W at x5,y6? 
 # choose any W
 anchor=next(iter(b0._make_group(6,5,'w').points)) if b0.get(6,5)=='w' else next(iter([pt for col,pt in b0.list_occupied_points() if col=='w']))
 # cavity points are (y,x)
 pts=tuple(sorted(cavity))
 @lru_cache(None)
 def rec(state, turn):
   # state tuple 0 empty,1 black,2 white for pts only; board reconstruct
   b=make(cavity)
   for pt,v in zip(pts,state):
     if v:
       try: b.play(pt[0],pt[1],'b' if v==1 else 'w')
       except Exception: return False
   st=status(b,anchor)
   if st=='dead': return False
   if st=='alive': return True
   moves=[i for i,v in enumerate(state) if v==0]
   if not moves: return False
   vals=[]
   for i in moves:
     ns=list(state); ns[i]=1 if turn=='b' else 2
     # reconstruct to catch captures among cavity? skip
     vals.append(rec(tuple(ns),'w' if turn=='b' else 'b'))
   return any(vals) if turn=='w' else all(vals)
 # This reconstruction fails captures because setup includes W at cavity? not; play captures maybe removed fixed; okay state assumes only direct occupancy, but captures can clear fixed stones not represented. status detects dead. 
 init=tuple(0 for _ in pts)
 print('cavity',[q(x) for x in cavity], 'root',status(b0,anchor))
 for i,pt in enumerate(pts):
   st=list(init);st[i]=1 if first=='b' else 2
   print(first,q(pt),rec(tuple(st),'w' if first=='b' else 'b'))

shapes=[['g8','h8','h9'],['g8','h8','h9','i9'],['g8','h8','i8','i9'],['g8','h8','h9','g9'],['g8','h8','i8','h9'],['g8','h8','i8','i9','h9']]
for ss in shapes:
  cavity={p(s) for s in ss}
  solve(cavity,'b')
PY"

